/**
 * Node-only Phaser stub. NEVER loaded in the browser (index.html's import map
 * resolves 'phaser' to esm.sh). Provides just enough surface for the pure-logic
 * modules that tests/run.mjs imports (Conductor extends Phaser.Events.EventEmitter).
 */
class EventEmitter {
  constructor() { this._listeners = new Map(); }
  on(event, fn, ctx) {
    if (!this._listeners.has(event)) this._listeners.set(event, []);
    this._listeners.get(event).push({ fn, ctx });
    return this;
  }
  once(event, fn, ctx) {
    const wrap = (...args) => { this.off(event, wrap); fn.apply(ctx, args); };
    return this.on(event, wrap, ctx);
  }
  off(event, fn) {
    const list = this._listeners.get(event);
    if (!list) return this;
    this._listeners.set(event, fn ? list.filter(l => l.fn !== fn) : []);
    return this;
  }
  emit(event, ...args) {
    const list = this._listeners.get(event) || [];
    for (const { fn, ctx } of [...list]) fn.apply(ctx, args);
    return list.length > 0;
  }
  removeAllListeners(event) {
    if (event) this._listeners.delete(event); else this._listeners.clear();
    return this;
  }
}

const Phaser = {
  Events: { EventEmitter },
  Math: {
    Clamp: (v, min, max) => Math.max(min, Math.min(max, v)),
    Linear: (a, b, t) => a + (b - a) * t,
    Between: (min, max) => Math.floor(Math.random() * (max - min + 1)) + min,
    FloatBetween: (min, max) => Math.random() * (max - min) + min
  },
  Utils: { Array: { GetRandom: arr => arr[Math.floor(Math.random() * arr.length)] } },
  AUTO: 0,
  Scale: { FIT: 3, CENTER_BOTH: 1 },
  Scene: class Scene { constructor(cfg) { this._cfg = cfg; } }
};

export default Phaser;
export { EventEmitter };
